/** Shared job model, payload validation, and processing constants. */

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The public job shape returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A validated submission, after defaults are applied, in fixed field order. */
export interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

/** An error that maps directly onto the API error envelope. */
export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
    readonly fields?: FieldError[],
  ) {
    super(message);
  }
}

export const MAX_INPUT_LENGTH = 1000;
export const MIN_STEPS = 1;
export const MAX_STEPS = 20;
export const DEFAULT_STEPS = 5;
export const MIN_FAIL_ATTEMPTS = 0;
export const MAX_FAIL_ATTEMPTS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;

/** Attempts in total before a job is failed for good. */
export const MAX_ATTEMPTS = 3;
export const TRANSIENT_FAILURE = 'transient failure';
/** Delay before a failed attempt is retried (within the 250 ms – 2 s window). */
export const RETRY_DELAY_MS = 500;
/** Time per processing step (within the 50 – 500 ms window). */
export const STEP_MS = 100;

const PAYLOAD_KEYS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

/** Validates the Idempotency-Key header. Multiple header values arrive joined by commas, which the pattern rejects. */
export function validateIdempotencyKey(raw: string | string[] | undefined): { key: string | null; errors: FieldError[] } {
  if (raw === undefined) return { key: null, errors: [] };
  if (typeof raw === 'string' && IDEMPOTENCY_KEY_PATTERN.test(raw)) return { key: raw, errors: [] };
  return {
    key: null,
    errors: [{ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$ and appear once' }],
  };
}

/** Validates a parsed JSON object body. Collects every offending field instead of stopping at the first. */
export function validatePayload(body: Record<string, unknown>): { payload: Payload | null; errors: FieldError[] } {
  const errors: FieldError[] = [];
  for (const name of Object.keys(body)) {
    if (!PAYLOAD_KEYS.has(name)) errors.push({ field: name, message: `unknown field "${name}"` });
  }

  let input = '';
  if (!Object.hasOwn(body, 'input')) {
    errors.push({ field: 'input', message: 'input is required' });
  } else {
    const value = body.input;
    if (typeof value !== 'string') {
      errors.push({ field: 'input', message: 'input must be a string' });
    } else if (value.length < 1 || value.length > MAX_INPUT_LENGTH) {
      errors.push({ field: 'input', message: `input must be 1 to ${MAX_INPUT_LENGTH} characters` });
    } else if (value.trim() === '') {
      errors.push({ field: 'input', message: 'input must not be only whitespace' });
    } else {
      input = value;
    }
  }

  const steps = intField(body, 'steps', MIN_STEPS, MAX_STEPS, DEFAULT_STEPS, errors);
  const failAttempts = intField(body, 'failAttempts', MIN_FAIL_ATTEMPTS, MAX_FAIL_ATTEMPTS, DEFAULT_FAIL_ATTEMPTS, errors);

  if (errors.length > 0) return { payload: null, errors };
  return { payload: { input, steps, failAttempts }, errors };
}

function intField(
  body: Record<string, unknown>,
  name: 'steps' | 'failAttempts',
  min: number,
  max: number,
  fallback: number,
  errors: FieldError[],
): number {
  if (!Object.hasOwn(body, name)) return fallback;
  const value = body[name];
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    errors.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return value;
}

