import { DatabaseSync, type StatementSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';
import type { Job, JobStatus, Payload } from './jobs.ts';

/** The worker counts as up only if its heartbeat is at most this old. */
export const HEARTBEAT_FRESH_MS = 3_000;

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  completed_steps INTEGER NOT NULL DEFAULT 0,
  output TEXT,
  error TEXT,
  idempotency_key TEXT UNIQUE,
  available_at INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
CREATE TABLE IF NOT EXISTS worker_heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  beat_at INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes and ensures the schema exists. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  // IF NOT EXISTS makes this safe to run from either process, in either start order.
  db.exec(SCHEMA);
  return db;
}

interface JobRow {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed_steps: number;
  output: string | null;
  error: string | null;
  idempotency_key: string | null;
  created_at: string;
  updated_at: string;
}

/** Maps a database row onto the public job shape. */
function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed_steps, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export type SubmitOutcome =
  | { kind: 'created'; job: Job }
  | { kind: 'replayed'; job: Job }
  | { kind: 'conflict' };

export interface Store {
  submit(payload: Payload, idempotencyKey: string | null): SubmitOutcome;
  list(): Job[];
  get(id: string): Job | undefined;
  workerUp(nowMs: number): boolean;
  beat(nowMs: number): void;
  clearBeat(): void;
  findRunning(): Job | undefined;
  claimNext(nowMs: number): Job | undefined;
  resetAttempt(id: string): void;
  setProgress(id: string, completed: number): void;
  scheduleRetry(id: string, availableAtMs: number): void;
  fail(id: string, message: string): void;
  complete(id: string, output: string): void;
}

/** Runs fn inside a short write transaction that takes the write lock up front. */
function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (error) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // The original error is the one worth reporting.
    }
    throw error;
  }
  return result;
}

export function createStore(db: DatabaseSync): Store {
  const stmt = {
    byKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
    byId: db.prepare('SELECT * FROM jobs WHERE id = ?'),
    insert: db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed_steps, output, error,
                         idempotency_key, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, 0, ?, ?)`,
    ),
    list: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
    running: db.prepare("SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1"),
    nextQueued: db.prepare("SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1"),
    claim: db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0, output = NULL, error = NULL, updated_at = ? WHERE id = ?",
    ),
    resetAttempt: db.prepare(
      'UPDATE jobs SET completed_steps = 0, output = NULL, error = NULL, updated_at = ? WHERE id = ? AND status = \'running\'',
    ),
    progress: db.prepare("UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND status = 'running'"),
    retry: db.prepare(
      "UPDATE jobs SET status = 'queued', completed_steps = 0, output = NULL, error = NULL, available_at = ?, updated_at = ? WHERE id = ? AND status = 'running'",
    ),
    fail: db.prepare(
      "UPDATE jobs SET status = 'failed', completed_steps = 0, output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'",
    ),
    complete: db.prepare(
      "UPDATE jobs SET status = 'completed', completed_steps = steps, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
    ),
    beat: db.prepare(
      'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
    ),
    clearBeat: db.prepare('DELETE FROM worker_heartbeat WHERE id = 1'),
    lastBeat: db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1'),
  };

  const oneJob = (s: StatementSync, ...params: (string | number | null)[]): Job | undefined => {
    const row = s.get(...params) as unknown as JobRow | undefined;
    return row === undefined ? undefined : toJob(row);
  };

  return {
    submit(payload, idempotencyKey) {
      return transaction(db, (): SubmitOutcome => {
        if (idempotencyKey !== null) {
          const existing = stmt.byKey.get(idempotencyKey) as unknown as JobRow | undefined;
          if (existing !== undefined) {
            const same =
              existing.input === payload.input &&
              existing.steps === payload.steps &&
              existing.fail_attempts === payload.failAttempts;
            return same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
          }
        }
        const id = randomUUID();
        const now = new Date().toISOString();
        stmt.insert.run(id, payload.input, payload.steps, payload.failAttempts, idempotencyKey, now, now);
        const job = oneJob(stmt.byId, id) as Job;
        return { kind: 'created', job };
      });
    },

    list() {
      return (stmt.list.all() as unknown as JobRow[]).map(toJob);
    },

    get(id) {
      return oneJob(stmt.byId, id);
    },

    workerUp(nowMs) {
      const row = stmt.lastBeat.get() as unknown as { beat_at: number } | undefined;
      return row !== undefined && nowMs - row.beat_at <= HEARTBEAT_FRESH_MS;
    },

    beat(nowMs) {
      stmt.beat.run(nowMs);
    },

    clearBeat() {
      stmt.clearBeat.run();
    },

    findRunning() {
      return oneJob(stmt.running);
    },

    claimNext(nowMs) {
      return transaction(db, () => {
        const next = stmt.nextQueued.get(nowMs) as unknown as JobRow | undefined;
        if (next === undefined) return undefined;
        stmt.claim.run(new Date().toISOString(), next.id);
        return oneJob(stmt.byId, next.id);
      });
    },

    resetAttempt(id) {
      stmt.resetAttempt.run(new Date().toISOString(), id);
    },

    setProgress(id, completed) {
      stmt.progress.run(completed, new Date().toISOString(), id);
    },

    scheduleRetry(id, availableAtMs) {
      stmt.retry.run(availableAtMs, new Date().toISOString(), id);
    },

    fail(id, message) {
      stmt.fail.run(message, new Date().toISOString(), id);
    },

    complete(id, output) {
      stmt.complete.run(output, new Date().toISOString(), id);
    },
  };
}

