import { createServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase, createStore } from './db.ts';
import {
  ApiError,
  validatePayload,
  validateIdempotencyKey,
  type FieldError,
} from './jobs.ts';

const db = openDatabase();
const store = createStore(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** Request bodies larger than this are rejected; the largest valid payload is well under it. */
const MAX_BODY_BYTES = 64 * 1024;

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, error: ApiError, headers: Record<string, string> = {}): void {
  const body: { error: { code: string; message: string; fields?: FieldError[] } } = {
    error: { code: error.code, message: error.message },
  };
  if (error.fields !== undefined) body.error.fields = error.fields;
  sendJson(res, error.status, body, headers);
}

/** Reads the whole body as bytes. Oversized bodies are drained but reported as a body error. */
function readBody(req: IncomingMessage): Promise<{ bytes: Buffer | null }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ bytes: tooLarge ? null : Buffer.concat(chunks) }));
    req.on('error', reject);
  });
}

const isJsonMediaType = (header: string | undefined): boolean =>
  header !== undefined && header.split(';')[0]!.trim().toLowerCase() === 'application/json';

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];
  const keyResult = validateIdempotencyKey(req.headers['idempotency-key']);
  fields.push(...keyResult.errors);

  const { bytes } = await readBody(req);
  let bodyChecked = false;
  if (!isJsonMediaType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (bytes === null) {
    fields.push({ field: 'body', message: `request body must not exceed ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
    } catch {
      fields.push({ field: 'body', message: 'request body must be valid JSON' });
      parsed = undefined;
      bodyChecked = true;
    }
    if (!bodyChecked) {
      if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
        fields.push({ field: 'body', message: 'request body must be a JSON object' });
      } else {
        const { payload, errors } = validatePayload(parsed as Record<string, unknown>);
        fields.push(...errors);
        if (fields.length === 0 && payload !== null) {
          const outcome = store.submit(payload, keyResult.key);
          if (outcome.kind === 'conflict') {
            throw new ApiError(409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
          }
          const status = outcome.kind === 'created' ? 201 : 200;
          return sendJson(res, status, outcome.job);
        }
      }
    }
  }

  throw new ApiError(400, 'invalid_request', 'The request is invalid.', fields);
}

function listJobs(_req: IncomingMessage, res: ServerResponse): void {
  sendJson(res, 200, { jobs: store.list() });
}

function getJob(_req: IncomingMessage, res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    throw new ApiError(404, 'not_found', 'Job not found.');
  }
  const job = store.get(id);
  if (job === undefined) throw new ApiError(404, 'not_found', 'Job not found.');
  sendJson(res, 200, job);
}

function health(_req: IncomingMessage, res: ServerResponse): void {
  sendJson(res, 200, { status: 'ok', worker: store.workerUp(Date.now()) ? 'up' : 'down' });
}

function serveUi(_req: IncomingMessage, res: ServerResponse): void {
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
  res.end(uiHtml);
}

type Handler = (req: IncomingMessage, res: ServerResponse, param: string) => void | Promise<void>;

interface Route {
  pattern: RegExp;
  methods: Record<string, Handler>;
}

const ROUTES: Route[] = [
  { pattern: /^\/$/, methods: { GET: serveUi } },
  { pattern: /^\/health$/, methods: { GET: health } },
  { pattern: /^\/api\/jobs$/, methods: { GET: listJobs, POST: createJob } },
  { pattern: /^\/api\/jobs\/([^/]+)$/, methods: { GET: getJob } },
];

