async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const route = ROUTES.find((r) => r.pattern.test(pathname));
  if (route === undefined) throw new ApiError(404, 'not_found', 'No such route.');

  const method = req.method ?? 'GET';
  const handler = route.methods[method];
  if (handler === undefined) {
    const allow = Object.keys(route.methods).join(', ');
    return sendError(res, new ApiError(405, 'method_not_allowed', `Method ${method} is not allowed here.`), { allow });
  }
  const param = route.pattern.exec(pathname)?.[1] ?? '';
  await handler(req, res, param);
}

const server: Server = createServer((req, res) => {
  handle(req, res).catch((error: unknown) => {
    if (res.headersSent) {
      res.destroy();
      return;
    }
    if (error instanceof ApiError) return sendError(res, error);
    console.error('unhandled request error:', error);
    sendError(res, new ApiError(500, 'internal_error', 'An unexpected error occurred.'));
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  // Stop accepting connections and let in-flight handlers finish. Each handler is short and
  // synchronous against the database, so the database is closed only after the server has drained.
  server.close(() => {
    db.close();
    process.exit(0);
  });
