  setTimeout(() => server.closeAllConnections(), 2_000).unref();
  setTimeout(() => {
    db.close();
    process.exit(0);
  }, 5_000).unref();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

