import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, createStore, type Store } from './db.ts';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, TRANSIENT_FAILURE, type Job } from './jobs.ts';

const HEARTBEAT_MS = 500;
const POLL_MS = 100;

const db = openDatabase();
const store: Store = createStore(db);
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    // Stop claiming new work. The current attempt runs to its final transition first.
    stopping = true;
  });
}

const beat = (): void => {
  try {
    store.beat(Date.now());
  } catch (error) {
    console.error('heartbeat failed:', error);
  }
};

/** Runs one attempt of a job whose attempt number is already recorded in the database. */
async function runAttempt(job: Job): Promise<void> {
  const attempt = job.attempts;

  // Simulated transient failure: decided at the first step, before any progress is made.
  if (attempt <= job.failAttempts) {
    if (attempt < MAX_ATTEMPTS) store.scheduleRetry(job.id, Date.now() + RETRY_DELAY_MS);
    else store.fail(job.id, TRANSIENT_FAILURE);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    store.setProgress(job.id, step);
  }
  store.complete(job.id, job.input.toUpperCase());
}

async function main(): Promise<void> {
  beat();
  const heartbeat = setInterval(beat, HEARTBEAT_MS);
  console.log('worker started');

  while (!stopping) {
    try {
      // This is the only worker, and it runs attempts one at a time. A job still marked running
      // at this point was interrupted by an earlier crash, so resume its recorded attempt.
      const interrupted = store.findRunning();
      let job: Job | undefined;
      if (interrupted !== undefined) {
        store.resetAttempt(interrupted.id);
        job = interrupted;
      } else {
        job = store.claimNext(Date.now());
      }

      if (job === undefined) {
        await sleep(POLL_MS);
        continue;
      }
      await runAttempt(job);
    } catch (error) {
      console.error('worker error:', error);
      await sleep(POLL_MS);
    }
  }

  clearInterval(heartbeat);
  store.clearBeat();
  db.close();
  console.log('worker stopped');
  process.exit(0);
}

void main();

